"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { useSocket } from "@/contexts/SocketContext";
import api from "@/services/api";
import AppLayout from "@/components/AppLayout";

export default function MessagesListPage() {
  const { user, loading } = useAuth();
  const socket = useSocket();
  const router = useRouter();

  const [users, setUsers] = useState([]);
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [lastMessages, setLastMessages] = useState({});
  const [search, setSearch] = useState("");

  useEffect(() => {
    if (!loading && !user) router.push("/login");
  }, [loading, user, router]);

  useEffect(() => {
    const fetchUsers = async () => {
      const res = await api.get("/api/users");
      setUsers(res.data.users || res.data);
    };

    const fetchLastMessages = async () => {
      const res = await api.get("/api/messages");
      const map = {};
      res.data.forEach((msg) => {
        const otherId =
          msg.sender_id === user.id ? msg.receiver_id : msg.sender_id;
        map[otherId] = msg;
      });
      setLastMessages(map);
    };

    if (user) {
      fetchUsers();
      fetchLastMessages();
    }
  }, [user]);

  useEffect(() => {
    if (!socket || !user) return;

    socket.emit("join", user.id);

    socket.on("user_online", (ids) => setOnlineUsers(ids));

    return () => {
      socket.off("user_online");
    };
  }, [socket, user]);

  const filteredUsers = users
    .filter((u) => u.id !== user?.id)
    .filter((u) => u.username.toLowerCase().includes(search.toLowerCase()));

  return (
    <AppLayout>
      <div className="max-w-lg mx-auto p-4">
        <h2 className="text-2xl font-bold mb-4 text-white">Messages</h2>
        <input
          type="text"
          placeholder="Search users..."
          className="w-full mb-4 p-2 rounded bg-gray-800 text-white"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <ul className="space-y-3">
          {filteredUsers.map((u) => {
            const isOnline = onlineUsers.includes(String(u.id));
            const lastMsg = lastMessages[u.id];

            return (
              <li
                key={u.id}
                className="flex justify-between items-center bg-gray-800 p-3 rounded-lg cursor-pointer hover:bg-gray-700"
                onClick={() => router.push(`/messages/${u.id}`)}
              >
                <div className="flex items-center gap-4">
                  <div className="relative">
                    <img
                      src={u.avatar}
                      alt={u.username}
                      className="w-12 h-12 rounded-full object-cover"
                    />
                    <span
                      className={`absolute bottom-0 right-0 w-3 h-3 rounded-full border-2 border-black ${
                        isOnline ? "bg-green-500" : "bg-gray-500"
                      }`}
                    />
                  </div>
                  <div>
                    <p className="text-white font-semibold">{u.username}</p>
                    {lastMsg && (
                      <p className="text-gray-400 text-sm truncate max-w-[200px]">
                        {lastMsg.sender_id === user.id ? "You: " : ""}
                        {lastMsg.content}
                      </p>
                    )}
                  </div>
                </div>
                {/* Unread badge (example logic — toggle this with real data if needed) */}
                {lastMsg && lastMsg.sender_id === u.id && (
                  <span className="text-red-500 text-sm">🔴</span>
                )}
              </li>
            );
          })}
        </ul>
      </div>
    </AppLayout>
  );
}
